private final class ChatKoboyoPathCache: @unchecked Sendable {
    static let shared = ChatKoboyoPathCache()
    private let lock = NSLock()
    private var cache: [ChatKoboyoMark: Path] = [:]

    func path(for mark: ChatKoboyoMark) -> Path {
        lock.lock()
        defer { lock.unlock() }
        if let cached = cache[mark] { return cached }
        let parsed = HomeSVGPathParser.parse(mark.pathData)
        cache[mark] = parsed
        return parsed
    }
}

struct ChatKoboyoShape: Shape {
    let mark: ChatKoboyoMark

    func path(in rect: CGRect) -> Path {
        let vb = mark.viewBox
        let scale = min(rect.width / vb.width, rect.height / vb.height)
        let dx = rect.minX + (rect.width - vb.width * scale) / 2
        let dy = rect.minY + (rect.height - vb.height * scale) / 2
        let transform = CGAffineTransform(a: scale, b: 0, c: 0, d: scale, tx: dx, ty: dy)
        return mark.renderedPath.applying(transform)
    }
}

/// 静态 Koboyo 字形；颜色由 `.foregroundStyle` 决定。
struct ChatKoboyoIcon: View {
    let mark: ChatKoboyoMark
    var size: CGFloat = 14

    init(_ mark: ChatKoboyoMark, size: CGFloat = 14) {
        self.mark = mark
        self.size = size
    }

    var body: some View {
        ChatKoboyoShape(mark: mark)
            .frame(width: size, height: size)
            .accessibilityHidden(true)
    }
}

/// UIKit 驱动的轻呼吸：思考进行中才闪，不旋转、不占 SwiftUI ViewGraph 帧预算。
struct ChatKoboyoSpinningIcon: UIViewRepresentable {
    let mark: ChatKoboyoMark
    let pointSize: CGFloat
    let tint: UIColor
    let isActive: Bool

    private static let pulseKey = "chat.koboyo.pulse"

    func makeUIView(context: Context) -> UIView {
        let host = UIView()
        host.backgroundColor = .clear
        host.setContentHuggingPriority(.required, for: .horizontal)
        host.setContentHuggingPriority(.required, for: .vertical)
        host.setContentCompressionResistancePriority(.required, for: .horizontal)
        host.setContentCompressionResistancePriority(.required, for: .vertical)

        let layer = CAShapeLayer()
        layer.fillColor = tint.cgColor
        host.layer.addSublayer(layer)
        context.coordinator.shapeLayer = layer
        layout(in: host, coordinator: context.coordinator)
        applyPulse(to: layer, active: isActive)
        context.coordinator.pulsing = isActive
        return host
    }

    func updateUIView(_ host: UIView, context: Context) {
        context.coordinator.shapeLayer?.fillColor = tint.cgColor
        layout(in: host, coordinator: context.coordinator)
        if context.coordinator.pulsing != isActive {
            applyPulse(to: context.coordinator.shapeLayer, active: isActive)
            context.coordinator.pulsing = isActive
        }
    }

    func sizeThatFits(_ proposal: ProposedViewSize, uiView: UIView, context: Context) -> CGSize? {
        CGSize(width: pointSize, height: pointSize)
    }

    func makeCoordinator() -> Coordinator {
        Coordinator()
    }

    final class Coordinator {
        var shapeLayer: CAShapeLayer?
        var pulsing = false
        var lastSize: CGFloat = 0
        var lastMark: ChatKoboyoMark?
    }

    private func layout(in host: UIView, coordinator: Coordinator) {
        host.bounds = CGRect(origin: .zero, size: CGSize(width: pointSize, height: pointSize))
        guard let shapeLayer = coordinator.shapeLayer else { return }
        if coordinator.lastMark != mark || coordinator.lastSize != pointSize {
            let vb = mark.viewBox
            let scale = pointSize / max(vb.width, vb.height)
            let dx = (pointSize - vb.width * scale) / 2
            let dy = (pointSize - vb.height * scale) / 2
            let transform = CGAffineTransform(a: scale, b: 0, c: 0, d: scale, tx: dx, ty: dy)
            shapeLayer.path = mark.renderedPath.applying(transform).cgPath
            coordinator.lastMark = mark
            coordinator.lastSize = pointSize
        }
        shapeLayer.frame = host.bounds
    }

    private func applyPulse(to layer: CAShapeLayer?, active: Bool) {
        guard let layer else { return }
        layer.removeAnimation(forKey: Self.pulseKey)
        guard active else {
            layer.opacity = 1
            return
        }
        let animation = CABasicAnimation(keyPath: "opacity")
        animation.fromValue = 1
        animation.toValue = 0.42
        animation.duration = 0.9
        animation.autoreverses = true
        animation.repeatCount = .infinity
        animation.timingFunction = CAMediaTimingFunction(name: .easeInEaseOut)
        layer.add(animation, forKey: Self.pulseKey)
    }
}
